function TextWidget({ value }: { value: { params: { options?: { text?: string } } } }) {
  let text = value.params.options?.text ?? "";
  text = text.replace(/\*\*(.*?)\*\*/g, "<b>$1</b>");
  text = text.replace(/\*(.*?)\*/g, "<i>$1</i>");
  return (
    <div>
      <span dangerouslySetInnerHTML={{ __html: text }} />
    </div>
  );
}

