import { useContext, useEffect } from 'react';
import { useOidc } from '@axa-fr/react-oidc';
import { NavigationContext } from '../contexts/NavigationProvider';

export function LoginForm() {
  const { isAuthenticated } = useOidc();
  const { setPath } = useContext(NavigationContext);
  const redirect = new URLSearchParams(window.location.search).get('redirect');

  useEffect(() => {
    if (isAuthenticated) {
      if (redirect) setPath(redirect);
      else setPath('/');
    }
  }, [isAuthenticated, setPath]);

  return null;
}

import express from 'express';
import path from 'path';
import { readFile, writeFile } from 'fs/promises';

const VAULT = '/home/me/vault';
const app = express();

app.get('/vault/*', async (req, res) => {
  const name = decodeURIComponent(req.path.slice(req.path.indexOf('/', 1) + 1));
  const full = path.join(VAULT, name);
  res.type('text/plain').send(await readFile(full, 'utf-8'));
});

app.put('/vault/*', async (req, res) => {
  const name = decodeURIComponent(req.path.slice(req.path.indexOf('/', 1) + 1));
  await writeFile(path.join(VAULT, name), req.body);
  res.sendStatus(204);
});

import http from 'node:http';
import path from 'node:path';
import { pack } from 'tar-fs';

const ROOT = '/srv/files';

http.createServer((req, res) => {
  const name = decodeURIComponent(req.url.replace('/api/v1', '') || '/');
  const cmd = name.replace('/', '');
  if (cmd.startsWith('pack')) {
    const target = cmd.replace(/^pack/, '');
    const dir = path.dirname(target);
    pack(path.join(ROOT, dir)).pipe(res);
  }
}).listen(8000);

import express from 'express';
import path from 'path';
import { readFile, rename, cp } from 'fs/promises';

const ROOT = '/srv/files';
const app = express();
app.use(express.json());

app.get('/markdown/*', async (req, res) => {
  const name = decodeURIComponent(req.path).replace('/markdown', '');
  const file = path.normalize(ROOT + name);
  res.type('text/html').send(await readFile(file, 'utf-8'));
});

app.put('/api/v1/*', async (req, res) => {
  const { from, to, names } = req.body;
  const cmd = req.params[0];
  if (cmd === 'rename') await rename(path.join(ROOT, from), path.join(ROOT, to));
  if (cmd === 'copy') await cp(path.join(ROOT, from), path.join(ROOT, to));
  res.sendStatus(200);
});

import express from 'express';
import fs from 'fs';
import path from 'path';

const DIR = path.join(process.env.HOME || '', '.app', 'enriched');
const app = express();

app.get('/api/sessions/:id', (req, res) => {
  const file = path.join(DIR, `${req.params.id}.json`);
  if (!fs.existsSync(file)) return res.sendStatus(404);
  res.json(JSON.parse(fs.readFileSync(file, 'utf-8')));
});

app.post('/api/enrich/:id', async (req, res) => {
  const file = path.join(DIR, `${req.params.id}.json`);
  fs.writeFileSync(file, JSON.stringify({ id: req.params.id }));
  res.sendStatus(204);
});

import { NextRequest, NextResponse } from 'next/server';
import { createReadStream, statSync } from 'fs';

export const GET = async (
  request: NextRequest,
  context: { params: Promise<{ path?: string[] }> }
) => {
  const { path } = await context.params;
  const filePath = process.env.UPLOAD_DIRECTORY + '/' + (path ?? []).join('/');
  const response = new NextResponse(createReadStream(filePath) as any);
  response.headers.set('content-length', String(statSync(filePath).size));
  return response;
};

import express from 'express';

const app = express();
app.use(express.json());

app.post('/api/import', (req, res) => {
  const basePath = new URL(req.body.repoUrl).pathname.split('/tree/')[1] || '';
  const entries = ['repo-main/skills/demo/SKILL.md', 'repo-main/README.md'];
  const pattern = new RegExp(`^[^/]+/${basePath}/SKILL\\.md$`);
  const found = entries.find((entry) => pattern.test(entry));
  res.json({ entry: found ?? null });
});

app.listen(3000);

const express = require('express');
const url = require('url');
const cookieParser = require('cookie-parser');

const app = express();
app.set('view engine', 'pug');
app.use(cookieParser());

app.get('/enrollment', (req, res) => {
  const query = url.parse(req.url, true).query;
  if (query.udid) {
    res.cookie('newudid', query.udid, { maxAge: 10 * 60 * 1000 });
    return res.redirect('/enrollment');
  }
  const cookie = req.cookies.newudid;
  if (cookie) return res.render('udid', { udid: cookie });
  res.redirect('/');
});

const http = require('http');
const url = require('url');
const querystring = require('querystring');

const db = { selectAll: (cols, where, group, cb) => cb(null, [{ name: where }]) };

http.createServer((req, res) => {
  const parsed = url.parse(req.url);
  const query = querystring.parse(parsed.query);
  db.selectAll('name, ticker', 'ticker="' + query.market.split('-')[1] + '"', '', (err, rows) => {
    res.end(JSON.stringify(rows));
  });
}).listen(8000);

import express from 'express';
import { createClient } from '@clickhouse/client';

const ch = createClient({ url: 'http://localhost:8123' });
const app = express();

app.get('/api/cohort', async (req, res) => {
  const { start, end } = req.query;
  const sql = `SELECT uniq(profile_id) AS count FROM events
    WHERE created_at BETWEEN toDate('${start}') AND toDate('${end}')`;
  const rows = await ch.query({ query: sql, format: 'JSONEachRow' });
  res.json(await rows.json());
});

app.listen(3000);

import express from 'express';
import axios from 'axios';
import privateIp from 'private-ip';

const app = express();
app.use(express.json());

function validateUrl(value) {
  const u = new URL(value);
  if (u.protocol !== 'http:' && u.protocol !== 'https:') throw new Error('Invalid URL');
  if (privateIp(u.hostname)) throw new Error('Invalid URL');
  return u;
}

app.post('/api/scan', async (req, res) => {
  const url = req.body.url;
  const response = await axios.get(url);
  res.json({ title: response.data.slice(0, 200) });
});

app.listen(3000);

'use client';

import { useEffect } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';

export function Client() {
  const router = useRouter();
  const callbackUrl = useSearchParams().get('callbackUrl') ?? '/';

  useEffect(() => {
    try {
      const url = new URL(callbackUrl, window.location.origin);
      if (url.pathname === '/' || url.pathname === '') return;
      router.push(callbackUrl);
    } catch {
      router.push(callbackUrl);
    }
  }, [callbackUrl, router]);

  return null;
}

import express from 'express';
import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();
const app = express();
app.use(express.json());

app.post('/embed/:embedId/stream-chat', async (req, res) => {
  const { embedId } = req.params;
  const { sessionId } = req.body;
  const chats = await prisma.embed_chats.findMany({
    where: { embed_id: embedId, session_id: sessionId },
  });
  res.json(chats);
});

app.listen(3000);
